import { useState } from 'react'
import Collapsible from '@/components/ui/Collapsible'
import Button from '@/components/ui/Button'

const Controlled = () => {
    const [isOpen, setIsOpen] = useState(false)

    return (
        <div className="max-w-md mx-auto">
            <div className="mb-4">
                <Button variant="solid" onClick={() => setIsOpen(!isOpen)}>
                    {isOpen ? 'Close' : 'Open'} Collapsible
                </Button>
            </div>
            <Collapsible
                open={isOpen}
                onOpenChange={setIsOpen}
                className="border border-gray-200 dark:border-gray-700 rounded-lg"
            >
                <Collapsible.Trigger>
                    Controlled Collapsible
                </Collapsible.Trigger>
                <Collapsible.Content className="px-4 pb-4">
                    <p>
                        This collapsible is controlled externally. You can use
                        the button above or click the trigger to toggle it. The
                        state is managed by the parent component.
                    </p>
                </Collapsible.Content>
            </Collapsible>
        </div>
    )
}

export default Controlled
import Collapsible from '@/components/ui/Collapsible'
import Button from '@/components/ui/Button'
import { HiChevronRight } from 'react-icons/hi'

const CustomTrigger = () => {
    return (
        <div className="max-w-md mx-auto">
            <Collapsible>
                <Collapsible.Trigger>
                    {({ isOpen, toggle }) => (
                        <Button
                            variant="subtle"
                            className="w-full justify-between"
                            onClick={toggle}
                            iconAlignment="end"
                            icon={
                                <HiChevronRight
                                    className={`transition-transform duration-200 ${isOpen ? 'rotate-90' : 'rotate-0'}`}
                                />
                            }
                        >
                            <span>Custom Trigger Button</span>
                        </Button>
                    )}
                </Collapsible.Trigger>
                <Collapsible.Content className="pt-4">
                    <p>
                        Using the render props pattern, you have full control
                        over the trigger appearance and behavior. The function
                        receives <code>isOpen</code> and <code>toggle</code>{' '}
                        props.
                    </p>
                </Collapsible.Content>
            </Collapsible>
        </div>
    )
}

export default CustomTrigger
import { useState } from 'react'
import Collapsible from '@/components/ui/Collapsible'

const Accordion = () => {
    const [openIndex, setOpenIndex] = useState<number | null>(0)

    const items = [
        {
            title: 'What is Collapsible?',
            content:
                'Collapsible is a component that allows you to show and hide content with smooth animations. It is useful for FAQs, accordions, and expandable sections.',
        },
        {
            title: 'How does it work?',
            content:
                'The component uses Framer Motion for smooth height animations. It supports both controlled and uncontrolled modes, and provides a flexible trigger system.',
        },
        {
            title: 'Can I customize the trigger?',
            content:
                'Yes! You can use the render props pattern to create fully custom triggers. The function receives isOpen and toggle props for complete control.',
        },
    ]

    const handleOpenChange = (index: number) => (open: boolean) => {
        setOpenIndex(open ? index : null)
    }

    return (
        <div className="max-w-md space-y-2 mx-auto">
            {items.map((item, index) => (
                <Collapsible
                    key={index}
                    open={openIndex === index}
                    onOpenChange={handleOpenChange(index)}
                    className="border border-gray-200 dark:border-gray-600 rounded-lg"
                >
                    <Collapsible.Trigger>{item.title}</Collapsible.Trigger>
                    <Collapsible.Content className="px-4 pb-4">
                        <p>{item.content}</p>
                    </Collapsible.Content>
                </Collapsible>
            ))}
        </div>
    )
}

export default Accordion
